import pandas as pd
import numpy as np
from collections import defaultdict

# Load data
trips = pd.read_csv('chunks_csv/cyclehire_w001.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Step 1: Validate all boroughs in trip data are in adjacency list
all_boroughs_trip = set(trips['StartBorough'].unique()).union(set(trips['EndBorough'].unique()))
all_boroughs_adj = set(adjacency['borough'].unique()).union(set(adjacency['neighbor'].unique()))
valid_boroughs = [b for b in all_boroughs_trip if b in all_boroughs_adj]

# Proceed with valid_boroughs

# Step 2: Compute SCI for each borough
# Departures
departures = trips.groupby('StartBorough').size().reindex(valid_boroughs, fill_value=0).to_dict()

# Self-contained trips
self_contained = trips[trips['StartBorough'] == trips['EndBorough']].groupby('StartBorough').size().reindex(valid_boroughs, fill_value=0).to_dict()

# Arrival share
total_arrivals = trips.groupby('EndBorough').size().reindex(valid_boroughs, fill_value=0)
total_arrivals_all = total_arrivals.sum()
arrival_share = total_arrivals / total_arrivals_all

# Expected self-contained trips
expected_self_contained = {b: departures[b] * arrival_share.loc[b] for b in valid_boroughs}

# SCI
sci_dict = {}
for b in valid_boroughs:
    expected = expected_self_contained[b]
    if expected == 0:
        sci = 0.0 if self_contained[b] == 0 else float('nan')
    else:
        sci = self_contained[b] / expected
    sci_dict[b] = sci

# Build adjacency dictionary
adj_dict = defaultdict(list)
for _, row in adjacency.iterrows():
    b1 = row['borough']
    b2 = row['neighbor']
    adj_dict[b1].append(b2)
    adj_dict[b2].append(b1)

# Compute average neighbor SCI
avg_neighbor_sci = {}
for b in valid_boroughs:
    neighbors = adj_dict.get(b, [])
    if not neighbors:
        avg_neighbor_sci[b] = np.nan
        continue
    neighbor_scis = [sci_dict[n] for n in neighbors if n in sci_dict]
    if not neighbor_scis:
        avg_neighbor_sci[b] = np.nan
    else:
        avg_neighbor_sci[b] = np.nanmean(neighbor_scis)

# Compute overall average SCI
valid_scis = [sci_dict[b] for b in valid_boroughs if not np.isnan(sci_dict[b])]
overall_avg_sci = np.nanmean(valid_scis)

# Prepare for permutation test
valid_boroughs_all = valid_boroughs
borough_to_index = {b: i for i, b in enumerate(valid_boroughs_all)}
original_scis_all = np.array([sci_dict[b] for b in valid_boroughs_all])

valid_boroughs_list = [b for b in valid_boroughs_all if not np.isnan(sci_dict[b]) and not np.isnan(avg_neighbor_sci[b])]

# Function to check if both values are above or below the overall average
def is_cluster(sci, neighbor_avg, overall_avg):
    if np.isnan(sci) or np.isnan(neighbor_avg):
        return False
    return (sci > overall_avg and neighbor_avg > overall_avg) or (sci < overall_avg and neighbor_avg < overall_avg)

# Original pattern for each borough
original_pattern = {b: is_cluster(sci_dict[b], avg_neighbor_sci[b], overall_avg_sci) for b in valid_boroughs_list}

# Now perform permutation test
num_permutations = 500
p_values = {b: 0 for b in valid_boroughs_list}

for perm in range(num_permutations):
    # Shuffle the SCIs
    shuffled_scis = np.random.permutation(original_scis_all)
    # For each borough in valid_boroughs_list, compute neighbor average using shuffled_scis
    for b in valid_boroughs_list:
        neighbors = adj_dict.get(b, [])
        neighbor_scis = []
        for n in neighbors:
            if n in borough_to_index:
                n_index = borough_to_index[n]
                neighbor_scis.append(shuffled_scis[n_index])
        if not neighbor_scis:
            neighbor_avg = np.nan
        else:
            neighbor_avg = np.nanmean(neighbor_scis)
        # Check if the condition is met
        sci = shuffled_scis[borough_to_index[b]]
        if is_cluster(sci, neighbor_avg, overall_avg_sci):
            p_values[b] += 1

# Compute p-values as proportion
for b in p_values:
    p_values[b] /= num_permutations

# Now, identify hot and cold spots
hot_cold = []
for b in valid_boroughs_list:
    sci = sci_dict[b]
    neighbor_avg = avg_neighbor_sci[b]
    if np.isnan(sci) or np.isnan(neighbor_avg):
        continue
    if is_cluster(sci, neighbor_avg, overall_avg_sci):
        if sci > overall_avg_sci:
            if p_values[b] < 0.05:
                hot_cold.append((b, 'HH', sci, p_values[b]))
        else:
            if p_values[b] < 0.05:
                hot_cold.append((b, 'LL', sci, p_values[b]))

# Print data_points_used
print(f"data_points_used = {len(trips)}")

# Print final answer
if hot_cold:
    final_answer = []
    for b, typ, sci, p in hot_cold:
        final_answer.append(f"{b} ({typ}, statistical method={p:.4f})")
    print(f"FINAL ANSWER: {', '.join(final_answer)}")
else:
    print("FINAL ANSWER: none")
